CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,pass_salt TEXT NOT NULL,pass_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',daily_limit INTEGER NOT NULL DEFAULT 100,disabled INTEGER NOT NULL DEFAULT 0,default_model TEXT,created_at INTEGER NOT NULL);
CREATE TABLE sessions(h TEXT PRIMARY KEY,uid INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,exp INTEGER NOT NULL);
CREATE TABLE api_keys(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,prefix TEXT NOT NULL,key_hash TEXT UNIQUE NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER,last_used_at INTEGER,use_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE usage(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,key_id INTEGER,model TEXT,tin INTEGER NOT NULL DEFAULT 0,tout INTEGER NOT NULL DEFAULT 0,ok INTEGER NOT NULL DEFAULT 1,ts INTEGER NOT NULL);
CREATE INDEX usage_u ON usage(user_id,ts);
CREATE TABLE errors(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER NOT NULL,route TEXT,msg TEXT);
CREATE TABLE settings(k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE TABLE rate(k TEXT NOT NULL,w INTEGER NOT NULL,c INTEGER NOT NULL,PRIMARY KEY(k,w));
